      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.25 date=2026-01-01 number=2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=30.25 due-total=3.03 overdue-total=3.03`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.25 due-total=3.03 overdue-total=3.03`,
      `STATEMENT sheet=${sheet} by=uma name=Ada due-total=3.03 claims=2`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=20.00 from=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=30.25 due-total=3.33 overdue-total=3.33`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.25 due-total=3.33 overdue-total=3.33`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=0.00 from=2026-04-01`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=20.00 date=2026-02-01 number=1 due=2.20`,
